package com.neonshift.app;
import android.content.*;import android.net.Uri;import org.json.*;import java.io.*;import java.nio.file.*;import java.math.*;import java.time.*;import java.util.*;
public class PairedInvoiceTest{
 static int checks;static void check(boolean ok,String label){checks++;if(!ok)throw new AssertionError(label);}interface Run{void run()throws Exception;}static void bad(Run action,String label)throws Exception{try{action.run();throw new AssertionError(label);}catch(IllegalArgumentException|IOException expected){checks++;}}
 static JSONObject row(Store store,int day,String end)throws Exception{JSONObject config=store.config().put("hourly",33.5).put("tax",30).put("payRule","marken").put("overtime",true);JSONObject payload=new JSONObject().put("requestId","pair-"+day).put("workDate","2026-11-"+day).put("entryMode","times").put("startTime","07:00").put("endTime",end).put("breakMinutes","0").put("config",config).put("client","Marken - UPS Healthcare").put("workType","Picker").put("worksite","Adelaide").put("km",100).put("extras",50);return store.saveJournal(payload);}
 static JSONObject linked(JSONObject s)throws Exception{return new JSONObject().put("date",Store.date(s)).put("address",s.getString("worksite")).put("hours",new BigDecimal(s.getLong("workedMs")).divide(new BigDecimal("3600000"),12,RoundingMode.HALF_UP).toPlainString()).put("sourceId",Store.id(s)).put("sourceRate",s.getJSONObject("config").get("hourly")).put("exactHours",true).put("overtimePremium",s.getJSONObject("totals").get("overtimePremium")).put("sourceFingerprint",Store.fingerprint(s)).put("timesheet",TimesheetData.fromSource(s));}
 public static void main(String[] args)throws Exception{
  Context context=new Context();Store store=new Store(context);InvoiceStore invoices=new InvoiceStore(context);JSONObject draft=invoices.draft(),profile=draft.getJSONObject("profile");profile.put("name","Example Worker").put("client","Marken - UPS Healthcare").put("client_email","accounts@example.com").put("description","Picker services provided in Adelaide").put("bank","Example Bank").put("account_name","Example Worker").put("bsb","000-000").put("account","00000000").put("timesheet_position","Picker").put("timesheet_location","Adelaide");draft.put("number",18).put("rate","33.50");JSONArray rows=new JSONArray();JSONObject first=row(store,18,"15:00");rows.put(linked(first)).put(linked(row(store,19,"16:17"))).put(linked(row(store,20,"16:04")));draft.put("rows",rows);invoices.validateDraftSources(draft);
  check(InvoiceEngine.total(InvoiceStore.items(draft)).toPlainString().equals("871.84"),"reference invoice gross total");check(first.getJSONObject("totals").getDouble("net")<first.getJSONObject("totals").getDouble("gross"),"personal costs separate");
  JSONObject wrong=new JSONObject(draft.toString());wrong.getJSONArray("rows").getJSONObject(0).getJSONObject("timesheet").put("regularMs",0);bad(()->invoices.validateDraftSources(wrong),"tampered timesheet rejected");JSONObject manual=new JSONObject(draft.toString());manual.getJSONArray("rows").getJSONObject(0).remove("timesheet");bad(()->InvoiceStore.items(manual),"manual line cannot fabricate shift times");
  File invoice=invoices.issue(draft);JSONObject record=invoices.find(invoice.getName());File sheet=invoices.timesheet(record,false);check(invoice.isFile()&&sheet.isFile()&&!invoice.equals(sheet),"two separate files issued");check(record.getString("total").equals("871.84"),"stored invoice amount");String pdf=new String(Files.readAllBytes(invoice.toPath()),"ISO-8859-1"),time=new String(Files.readAllBytes(sheet.toPath()),"ISO-8859-1");check(pdf.contains("871.84")&&!pdf.contains("22:30"),"invoice hides hours");check(time.contains("22:30")&&time.contains("2:21"),"timesheet shows all hours");
  Intent share=InvoiceShare.intent(invoice,sheet,record);ArrayList<Uri> uris=share.getParcelableArrayListExtra(Intent.EXTRA_STREAM);check(Intent.ACTION_SEND_MULTIPLE.equals(share.getAction()),"multi attachment share action");check(share.getStringArrayExtra(Intent.EXTRA_EMAIL)[0].equals("accounts@example.com"),"configured recipient preserved");JSONObject fallback=new JSONObject(record.toString()).put("email","");check(InvoiceShare.intent(invoice,sheet,fallback).getStringArrayExtra(Intent.EXTRA_EMAIL)[0].equals("accounts@sarecruitment.com.au"),"Marken fallback recipient");check(uris.size()==2&&!uris.get(0).toString().equals(uris.get(1).toString()),"two distinct attachment URIs");check(share.getClipData().getItemCount()==2&&(share.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0,"read grants for both documents");check(share.getStringExtra(Intent.EXTRA_TEXT).contains("for review")&&!share.getStringExtra(Intent.EXTRA_TEXT).contains("signed timesheet"),"unsigned document never claimed signed");
  bad(()->invoices.attachSigned(invoice.getName(),new ByteArrayInputStream("not pdf".getBytes())),"invalid signed attachment rejected");invoices.attachSigned(invoice.getName(),new ByteArrayInputStream(Files.readAllBytes(sheet.toPath())));record=invoices.find(invoice.getName());File signed=invoices.timesheet(record,true);check(signed.getName().startsWith("timesheet_signed_"),"user imported signed version selected");check(Arrays.equals(Files.readAllBytes(signed.toPath()),Files.readAllBytes(sheet.toPath())),"imported PDF content preserved");check(InvoiceShare.intent(invoice,signed,record).getStringExtra(Intent.EXTRA_TEXT).contains("signed timesheet"),"email uses imported signed document");
  JSONObject next=invoices.draft();next.getJSONObject("profile").put("client","Marken");next.put("number",19).put("rows",new JSONArray().put(linked(row(store,17,"15:00"))));File collision=new File(invoices.folder(),"timesheet_019_"+InvoiceStore.today()+".pdf");Files.write(collision.toPath(),"sentinel".getBytes());bad(()->invoices.issue(next),"existing timesheet never overwritten");check(new String(Files.readAllBytes(collision.toPath())).equals("sentinel"),"failed issue preserves existing file");
  Context groupingContext=new Context();Store journal=new Store(groupingContext);InvoiceStore grouping=new InvoiceStore(groupingContext);JSONObject grouped=grouping.draft();grouped.getJSONObject("profile").put("name","Example Worker").put("client","Example Client").put("description","Site services").put("bank","Example Bank").put("account_name","Example Worker").put("bsb","000000").put("account","00000000");
  JSONObject cfg=journal.config().put("currency","AUD").put("hourly",40).put("overtime",false).put("payRule","none");
  JSONObject payload=new JSONObject().put("requestId","group-1").put("workDate","2026-11-18").put("entryMode","times").put("startTime","07:00").put("endTime","10:01").put("breakMinutes","0").put("lunchMinutes","0").put("config",cfg).put("client","Example Client").put("worksite","Site A").put("km",10).put("extras",20);
  JSONObject saved=journal.saveJournal(payload);grouped.put("number",18).put("rate","999").put("aggregationOnly",true).put("rows",new JSONArray().put(new JSONObject().put("sourceId",Store.id(saved))));grouping.saveDraft(grouped);grouped=grouping.draft();
  check(grouped.getJSONArray("rows").getJSONObject(0).getDouble("sourceRate")==40,"source rate overrides invoice rate without overtime");
  check(InvoiceEngine.total(InvoiceStore.items(grouped)).toPlainString().equals("120.67"),"exact shift gross, no quarter-hour ceiling or personal cost deduction");grouping.validateDraftSources(grouped);
  JSONObject edited=new JSONObject(payload.toString()).put("id",Store.id(saved)).put("endTime","11:00");journal.saveJournal(edited);JSONObject synced=grouping.draft();check(synced.getJSONArray("rows").getJSONObject(0).getDouble("sourceGross")==160,"History save updates persisted draft without manual refresh");
  JSONObject forged=new JSONObject(synced.toString());forged.getJSONArray("rows").getJSONObject(0).put("sourceGross",1);bad(()->grouping.validateDraftSources(forged),"cannot override gross in composer");
  File firstGroup=grouping.issue(synced);byte[] original=Files.readAllBytes(firstGroup.toPath());JSONObject secondPayload=new JSONObject(payload.toString()).put("requestId","group-2").put("startTime","12:00").put("endTime","14:00");JSONObject second=journal.saveJournal(secondPayload);JSONObject other=grouping.draft();other.put("rows",new JSONArray().put(new JSONObject().put("sourceId",Store.id(second))));other=grouping.refreshSources(other);File secondGroup=grouping.issue(other);check(!firstGroup.equals(secondGroup)&&grouping.records().length()==2,"two invoices on same week/date with different shift times");
  JSONObject duplicate=grouping.draft();duplicate.put("rows",synced.getJSONArray("rows"));bad(()->grouping.issue(duplicate),"shift cannot be billed twice");
  JSONObject pending=grouping.draft();pending.put("rows",new JSONArray().put(new JSONObject().put("sourceId",Store.id(second))));grouping.saveDraft(pending);journal.removeJournal(Store.id(second),true);check(grouping.draft().getJSONArray("rows").length()==0,"deleted History shift removed from draft");check(Arrays.equals(original,Files.readAllBytes(firstGroup.toPath())),"issued PDF remains immutable");
  System.out.println("PASS: "+checks+" real paired invoice/store/share checks, signed import and immutable file collision protection.");
 }
}
